//! The parser: a hand-written port of Nix's `parser.y`.
//!
//! Nix's grammar is LALR(1), generated by bison. This is a recursive-descent
//! parser with a precedence-climbing loop for the operator level, written to
//! produce exactly the same trees, the same desugarings and the same error
//! messages. Where bison's error messages depend on the automaton (which
//! tokens it lists after "expecting"), the lists are reproduced at each site.
//! Checks bison makes in a rule's action happen when the whole rule has
//! been read, so they are made here after the rule's last part too: an
//! error inside a function body is reported before duplicate formals.

mod bindings;
mod indent;

use std::collections::VecDeque;

use crate::ast::{
    AttrDef, AttrName, AttrSet, AttrValue, BinOp, Expr, Formal, Formals, Name, PathAnchor, Pos,
};
use crate::error::{ParseError, Warning};
use crate::lexer::{Lexer, Tok, Token};
use crate::path::resolve_path_literal;
use crate::{STACK_RED_ZONE, STACK_SEGMENT};
use bindings::{add_attr, dup_inherit, AttrIndex};
use indent::{strip_indentation, IndPart};

/// Settings that change what the parser accepts.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ParseOptions {
    /// Accept the `|>` and `<|` operators (Nix's `pipe-operators`
    /// experimental feature). Off by default, as in Nix.
    pub pipe_operators: bool,
    /// The `lint-*` settings.
    pub lints: Lints,
}

/// How the parser treats a deprecated or non-portable construct (Nix's
/// `Diagnose`, the value of a `lint-*` setting).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub enum Diagnose {
    /// Accept it silently (the default).
    #[default]
    Ignore,
    /// Accept it with a [`Warning::Lint`].
    Warn,
    /// Reject it with a parse error.
    Fatal,
}

impl Diagnose {
    /// Parses a setting's value: `ignore`, `warn` or `fatal`.
    pub fn parse(s: &str) -> Option<Diagnose> {
        match s {
            "ignore" => Some(Diagnose::Ignore),
            "warn" => Some(Diagnose::Warn),
            "fatal" => Some(Diagnose::Fatal),
            _ => None,
        }
    }

    /// The setting's value as Nix spells it.
    pub fn name(self) -> &'static str {
        match self {
            Diagnose::Ignore => "ignore",
            Diagnose::Warn => "warn",
            Diagnose::Fatal => "fatal",
        }
    }
}

/// Nix's `lint-*` settings (`EvalSettings`), all `ignore` by default.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct Lints {
    /// `lint-url-literals`: unquoted URLs (`http://example.org`).
    pub url_literals: Diagnose,
    /// `lint-short-path-literals`: relative paths that do not start with
    /// `./` or `../` (`foo/bar`).
    pub short_path_literals: Diagnose,
    /// `lint-absolute-path-literals`: absolute paths (`/etc/hosts`); also
    /// home paths, which pure evaluation rejects before the lint.
    pub absolute_path_literals: Diagnose,
}

/// Parses a complete Nix expression.
///
/// `base_dir` is the absolute directory relative path literals are resolved
/// against (the directory of the file, or the working directory for stdin
/// and command-line expressions): bytes, as Nix's paths are, which the
/// resolved literals keep. Errors and warnings carry byte positions;
/// [`ParseError::render`] and [`Warning::render`] show them for an origin.
///
/// The warnings Nix logs while parsing are appended to `warnings` as they
/// are found, so those found before an error are there too: Nix prints
/// them before the error.
///
/// Evaluation is always pure, so `~/…` path literals are an error.
pub fn parse(
    src: &[u8],
    base_dir: &(impl AsRef<[u8]> + ?Sized),
    options: &ParseOptions,
    warnings: &mut Vec<Warning>,
) -> Result<Expr, ParseError> {
    parse_with_base(src, base_dir.as_ref(), options, warnings)
}

/// [`parse`] for a base directory given as bytes.
fn parse_with_base(
    src: &[u8],
    base_dir: &[u8],
    options: &ParseOptions,
    warnings: &mut Vec<Warning>,
) -> Result<Expr, ParseError> {
    let mut parser = Parser {
        lexer: Lexer::new(src, options),
        lookahead: VecDeque::new(),
        base_dir,
        lints: options.lints,
        warnings,
    };
    let expr = parser.parse_expr()?;
    if !parser.at(Tok::Eof)? {
        return Err(parser.syntax_error(Some("end of file")));
    }
    Ok(expr)
}

struct Parser<'a> {
    lexer: Lexer<'a>,
    /// Tokens read but not consumed. Bison reads at most one token beyond
    /// what it has shifted; this parser looks further only where it must
    /// decide between a function head and an attribute set.
    lookahead: VecDeque<Token<'a>>,
    base_dir: &'a [u8],
    lints: Lints,
    warnings: &'a mut Vec<Warning>,
}

/// Where a list of bindings appears, for the "expecting" part of the error
/// bison reports when a binding does not start correctly.
#[derive(Clone, Copy, PartialEq, Eq)]
enum BindsContext {
    /// `{ … }`: bison has already decided on bindings and expects 'inherit'.
    Braces,
    /// `rec { … }` and `let { … }`.
    RecBraces,
    /// `let … in`.
    LetIn,
}

impl BindsContext {
    fn closer(self) -> Tok<'static> {
        match self {
            BindsContext::Braces | BindsContext::RecBraces => Tok::RBrace,
            BindsContext::LetIn => Tok::In,
        }
    }

    fn expecting(self) -> &'static str {
        match self {
            BindsContext::Braces => "'inherit'",
            BindsContext::RecBraces => "'inherit' or '}'",
            BindsContext::LetIn => "'in' or 'inherit'",
        }
    }
}

const EXPECTING_ATTR: &str = "identifier or 'or' or '${' or '\"'";

/// Operator associativity, from `parser.y`'s `%left`/`%right`/`%nonassoc`
/// table.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Assoc {
    Left,
    Right,
    None,
}

const PREC_NOT: u8 = 7;
const PREC_NEGATE: u8 = 12;

/// Precedence level (higher binds tighter) and associativity of a binary
/// operator token.
fn binary_op(tok: &Tok<'_>) -> Option<(u8, Assoc)> {
    Some(match tok {
        Tok::Impl => (1, Assoc::Right),
        Tok::Or => (2, Assoc::Left),
        Tok::And => (3, Assoc::Left),
        Tok::Eq | Tok::NEq => (4, Assoc::None),
        Tok::Lt | Tok::Gt | Tok::Leq | Tok::Geq => (5, Assoc::None),
        Tok::Update => (6, Assoc::Right),
        Tok::Plus | Tok::Minus => (8, Assoc::Left),
        Tok::Star | Tok::Slash => (9, Assoc::Left),
        Tok::Concat => (10, Assoc::Right),
        Tok::Question => (11, Assoc::None),
        _ => return None,
    })
}

/// Can this token start `expr_select` (and so `expr_simple`)?
fn starts_simple(tok: &Tok<'_>) -> bool {
    matches!(
        tok,
        Tok::Id(_)
            | Tok::Int(_)
            | Tok::Float(_)
            | Tok::Quote
            | Tok::IndStringOpen
            | Tok::Path(_)
            | Tok::HPath(_)
            | Tok::SPath(_)
            | Tok::Uri(_)
            | Tok::LParen
            | Tok::Let
            | Tok::Rec
            | Tok::LBrace
            | Tok::LBracket
    )
}

/// Can this token start an attribute name (`attr` or `string_attr`)?
fn starts_attr(tok: &Tok<'_>) -> bool {
    matches!(tok, Tok::Id(_) | Tok::OrKw | Tok::Quote | Tok::DollarCurly)
}

fn name(bytes: &[u8]) -> Name {
    Name::new(bytes)
}

fn var(pos: Pos, name: &str) -> Expr {
    Expr::Var {
        pos,
        name: Name::from(name),
    }
}

fn boxed(e: Expr) -> Box<Expr> {
    Box::new(e)
}

impl<'a> Parser<'a> {
    fn fill(&mut self, n: usize) -> Result<(), ParseError> {
        while self.lookahead.len() <= n {
            let tok = self.lexer.next_token()?;
            self.lookahead.push_back(tok);
        }
        Ok(())
    }

    fn peek(&mut self) -> Result<&Token<'a>, ParseError> {
        self.peek_nth(0)
    }

    fn peek_nth(&mut self, n: usize) -> Result<&Token<'a>, ParseError> {
        self.fill(n)?;
        Ok(&self.lookahead[n])
    }

    fn peek_tok(&mut self) -> Result<&Tok<'a>, ParseError> {
        Ok(&self.peek()?.tok)
    }

    fn peek_pos(&mut self) -> Result<Pos, ParseError> {
        Ok(self.peek()?.pos())
    }

    fn bump(&mut self) -> Result<Token<'a>, ParseError> {
        self.fill(0)?;
        Ok(self.lookahead.pop_front().expect("filled"))
    }

    fn at(&mut self, tok: Tok<'_>) -> Result<bool, ParseError> {
        Ok(*self.peek_tok()? == tok)
    }

    /// Consumes `tok` or fails with "unexpected X, expecting `tok`".
    fn expect(&mut self, tok: Tok<'static>) -> Result<Token<'a>, ParseError> {
        if self.at(tok.clone())? {
            self.bump()
        } else {
            Err(self.syntax_error(Some(tok.describe())))
        }
    }

    /// "syntax error, unexpected X[, expecting Y]" at the lookahead token.
    fn syntax_error(&mut self, expecting: Option<&str>) -> ParseError {
        match self.peek() {
            Ok(tok) => syntax_error_at(tok, expecting),
            Err(e) => e,
        }
    }

    /// Nix's `diagnose` for a `lint-*` setting: nothing at `ignore`, a
    /// warning at `warn`, an error at `fatal`, with the message `msg`
    /// makes (told whether it is fatal) and the setting's name after it.
    fn diagnose(
        &mut self,
        level: Diagnose,
        setting: &str,
        pos: Pos,
        msg: impl FnOnce(bool) -> String,
    ) -> Result<(), ParseError> {
        match level {
            Diagnose::Ignore => Ok(()),
            Diagnose::Warn => {
                self.warnings.push(Warning::Lint {
                    msg: format!("{} ({setting})", msg(false)),
                    pos,
                });
                Ok(())
            }
            Diagnose::Fatal => Err(ParseError::new(format!("{} ({setting})", msg(true)), pos)),
        }
    }

    // ----- expr_function ---------------------------------------------------

    /// Every recursive descent into a sub-expression passes through here.
    /// Nix source can nest arbitrarily deep (generated nixpkgs files do), so
    /// the stack is grown on demand rather than relying on the thread's
    /// default, which is 2 MiB on spawned threads.
    fn parse_expr(&mut self) -> Result<Expr, ParseError> {
        stacker::maybe_grow(STACK_RED_ZONE, STACK_SEGMENT, || self.parse_expr_function())
    }

    fn parse_expr_function(&mut self) -> Result<Expr, ParseError> {
        // Only the token kind is needed to dispatch; cloning it is cheap
        // because no string token can start an expression.
        match self.peek_tok()?.clone() {
            Tok::Id(_) => match self.peek_nth(1)?.tok {
                Tok::Colon => {
                    let id = self.bump()?;
                    self.bump()?;
                    let body = self.parse_expr()?;
                    Ok(Expr::Lambda {
                        pos: id.pos(),
                        arg: Some(id_name(&id)),
                        formals: None,
                        body: boxed(body),
                    })
                }
                Tok::At => {
                    let id = self.bump()?;
                    self.bump()?;
                    self.expect(Tok::LBrace)?;
                    let formals = self.parse_formals()?;
                    self.expect(Tok::Colon)?;
                    let arg = id_name(&id);
                    let body = self.parse_expr()?;
                    // Bison checks the formals when it reduces the whole
                    // rule, so an error in the body is reported first.
                    validate_formals(&formals, id.pos(), Some(&arg))?;
                    Ok(Expr::Lambda {
                        pos: id.pos(),
                        arg: Some(arg),
                        formals: Some(Box::new(formals)),
                        body: boxed(body),
                    })
                }
                _ => self.parse_expr_if(),
            },
            Tok::LBrace if self.starts_formals()? => {
                let brace = self.bump()?;
                let formals = self.parse_formals()?;
                let arg = match self.peek_tok()? {
                    Tok::Colon => None,
                    Tok::At => {
                        self.bump()?;
                        let Tok::Id(_) = self.peek_tok()? else {
                            return Err(self.syntax_error(Some("identifier")));
                        };
                        let id = self.bump()?;
                        Some(id_name(&id))
                    }
                    _ => return Err(self.syntax_error(Some("':' or '@'"))),
                };
                self.expect(Tok::Colon)?;
                let body = self.parse_expr()?;
                validate_formals(&formals, brace.pos(), arg.as_ref())?;
                Ok(Expr::Lambda {
                    pos: brace.pos(),
                    arg,
                    formals: Some(Box::new(formals)),
                    body: boxed(body),
                })
            }
            Tok::Assert => {
                let kw = self.bump()?;
                let cond = self.parse_expr()?;
                self.expect(Tok::Semi)?;
                let body = self.parse_expr()?;
                Ok(Expr::Assert {
                    pos: kw.pos(),
                    cond: boxed(cond),
                    body: boxed(body),
                })
            }
            Tok::With => {
                let kw = self.bump()?;
                let attrs = self.parse_expr()?;
                self.expect(Tok::Semi)?;
                let body = self.parse_expr()?;
                Ok(Expr::With {
                    pos: kw.pos(),
                    attrs: boxed(attrs),
                    body: boxed(body),
                })
            }
            Tok::Let if self.peek_nth(1)?.tok != Tok::LBrace => {
                let kw = self.bump()?;
                let attrs = self.parse_binds(BindsContext::LetIn)?;
                let body = self.parse_expr()?;
                // Checked when bison reduces the whole rule, after the body.
                if !attrs.dynamic_attrs.is_empty() {
                    return Err(ParseError::new(
                        "dynamic attributes not allowed in let",
                        kw.pos(),
                    ));
                }
                Ok(Expr::Let {
                    attrs: Box::new(attrs),
                    body: boxed(body),
                })
            }
            _ => self.parse_expr_if(),
        }
    }

    /// After a `{`: is this a function head (`{ a, b }:`) rather than an
    /// attribute set? Decided from the next one or two tokens, as the LALR
    /// automaton does.
    fn starts_formals(&mut self) -> Result<bool, ParseError> {
        Ok(match self.peek_nth(1)?.tok {
            Tok::Ellipsis => true,
            Tok::RBrace => matches!(self.peek_nth(2)?.tok, Tok::Colon | Tok::At),
            Tok::Id(_) => matches!(
                self.peek_nth(2)?.tok,
                Tok::Comma | Tok::Question | Tok::RBrace
            ),
            _ => false,
        })
    }

    /// Parses `formals '}'` after the opening brace, including the empty and
    /// `...` forms.
    fn parse_formals(&mut self) -> Result<Formals, ParseError> {
        let mut formals = Vec::new();
        let mut ellipsis = false;
        loop {
            match self.peek_tok()? {
                Tok::RBrace => {
                    self.bump()?;
                    break;
                }
                Tok::Ellipsis => {
                    self.bump()?;
                    ellipsis = true;
                    self.expect(Tok::RBrace)?;
                    break;
                }
                Tok::Id(_) => {
                    let id = self.bump()?;
                    let default = if self.at(Tok::Question)? {
                        self.bump()?;
                        Some(boxed(self.parse_expr()?))
                    } else {
                        None
                    };
                    formals.push(Formal {
                        pos: id.pos(),
                        name: id_name(&id),
                        default,
                    });
                    match self.peek_tok()? {
                        Tok::Comma => {
                            self.bump()?;
                        }
                        Tok::RBrace => {}
                        _ => return Err(self.syntax_error(Some("'}' or ','"))),
                    }
                }
                _ => return Err(self.syntax_error(Some("identifier or '...' or '}'"))),
            }
        }
        Ok(Formals { formals, ellipsis })
    }

    // ----- expr_if ---------------------------------------------------------

    fn parse_expr_if(&mut self) -> Result<Expr, ParseError> {
        if self.at(Tok::If)? {
            let kw = self.bump()?;
            let cond = self.parse_expr()?;
            self.expect(Tok::Then)?;
            let then_ = self.parse_expr()?;
            self.expect(Tok::Else)?;
            let else_ = self.parse_expr()?;
            return Ok(Expr::If {
                pos: kw.pos(),
                cond: boxed(cond),
                then_: boxed(then_),
                else_: boxed(else_),
            });
        }
        let first = self.parse_expr_op(0)?;
        match self.peek_tok()? {
            Tok::PipeFrom => {
                // `f <| g <| x` is `f (g x)`: each call is positioned at the
                // `<|` right after its function.
                let mut funs = vec![first];
                let mut ops = Vec::new();
                while self.at(Tok::PipeFrom)? {
                    let op = self.bump()?;
                    ops.push(op.pos());
                    funs.push(self.parse_expr_op(0)?);
                }
                let mut result = funs.pop().expect("at least two items");
                while let Some(fun) = funs.pop() {
                    let pos = ops.pop().expect("one operator per function");
                    result = make_call(pos, fun, result);
                }
                Ok(result)
            }
            Tok::PipeInto => {
                // `x |> f |> g` is `g (f x)`: left-associative.
                let mut acc = first;
                while self.at(Tok::PipeInto)? {
                    let op = self.bump()?;
                    let fun = self.parse_expr_op(0)?;
                    acc = make_call(op.pos(), fun, acc);
                }
                Ok(acc)
            }
            _ => Ok(first),
        }
    }

    // ----- expr_op ---------------------------------------------------------

    /// Precedence climbing over `expr_op`. `min_prec` is the lowest
    /// precedence level this call may consume.
    fn parse_expr_op(&mut self, min_prec: u8) -> Result<Expr, ParseError> {
        stacker::maybe_grow(STACK_RED_ZONE, STACK_SEGMENT, || {
            self.parse_expr_op_inner(min_prec)
        })
    }

    fn parse_expr_op_inner(&mut self, min_prec: u8) -> Result<Expr, ParseError> {
        let start = self.peek_pos()?;
        let mut lhs = match self.peek_tok()? {
            Tok::Bang => {
                self.bump()?;
                let operand = self.parse_expr_op(PREC_NOT + 1)?;
                Expr::Not(boxed(operand))
            }
            Tok::Minus => {
                let op = self.bump()?;
                let operand = self.parse_expr_op(PREC_NEGATE + 1)?;
                Expr::Call {
                    pos: op.pos(),
                    fun: boxed(var(Pos::NONE, "__sub")),
                    args: vec![
                        Expr::Int {
                            pos: Pos::NONE,
                            value: 0,
                        },
                        operand,
                    ],
                }
            }
            _ => self.parse_expr_app()?,
        };
        while let Some((prec, assoc)) = binary_op(self.peek_tok()?) {
            if prec < min_prec {
                break;
            }
            let op = self.bump()?;
            if op.tok == Tok::Question {
                let path = self.parse_attrpath()?;
                lhs = Expr::HasAttr {
                    subject: boxed(lhs),
                    path,
                };
                continue;
            }
            let rhs_start = self.peek_pos()?;
            let rhs = self.parse_expr_op(if assoc == Assoc::Right {
                prec
            } else {
                prec + 1
            })?;
            lhs = build_binary(&op.tok, op.pos(), start, lhs, rhs_start, rhs);
            // `%nonassoc`: `a == b == c` is an error at the second operator.
            if assoc == Assoc::None && binary_op(self.peek_tok()?).is_some_and(|(p, _)| p == prec) {
                return Err(self.syntax_error(None));
            }
        }
        Ok(lhs)
    }

    // ----- expr_app / expr_select / expr_simple ----------------------------

    fn parse_expr_app(&mut self) -> Result<Expr, ParseError> {
        let start = self.peek_pos()?;
        // `expr_app: expr_select` resets a "cursed or": `map or [ ]` is
        // an application whatever `or` becomes.
        let mut fun = self.parse_expr_select()?.0;
        while starts_simple(self.peek_tok()?) {
            let arg = self.parse_expr_select_warn()?;
            fun = make_call(start, fun, arg);
        }
        Ok(fun)
    }

    /// `expr_select` where Nix's rule calls `warnIfCursedOr` on it: an
    /// argument, a list element, or the default after `or`.
    fn parse_expr_select_warn(&mut self) -> Result<Expr, ParseError> {
        let (e, cursed_or) = self.parse_expr_select()?;
        if let Some(end) = cursed_or {
            self.warnings.push(Warning::CursedOr { pos: e.pos(), end });
        }
        Ok(e)
    }

    /// `expr_select`, and for `expr_simple OR_KW` (a "cursed or": `or` as
    /// an argument, Nix issue 11118) the end of the `or`, which the rule
    /// that uses the expression either warns about or discards.
    fn parse_expr_select(&mut self) -> Result<(Expr, Option<Pos>), ParseError> {
        let start = self.peek_pos()?;
        let subject = self.parse_expr_simple()?;
        match self.peek_tok()? {
            Tok::Dot => {
                self.bump()?;
                let path = self.parse_attrpath()?;
                let default = if self.at(Tok::OrKw)? {
                    self.bump()?;
                    Some(boxed(self.parse_expr_select_warn()?))
                } else {
                    None
                };
                Ok((
                    Expr::Select {
                        pos: start,
                        subject: boxed(subject),
                        path,
                        default,
                    },
                    None,
                ))
            }
            Tok::OrKw => {
                // Backwards compatibility: `or` used as an identifier is an
                // argument to the preceding expression.
                let or = self.bump()?;
                let call = Expr::Call {
                    pos: start,
                    fun: boxed(subject),
                    args: vec![var(start, "or")],
                };
                Ok((call, Some(Pos(or.end))))
            }
            _ => Ok((subject, None)),
        }
    }

    fn parse_expr_simple(&mut self) -> Result<Expr, ParseError> {
        // Every alternative consumes the token or fails, so take it now.
        let tok = self.bump()?;
        let pos = tok.pos();
        match tok.tok {
            Tok::Id(text) => {
                if text == b"__curPos" {
                    Ok(Expr::CurPos { pos })
                } else {
                    Ok(Expr::Var {
                        pos,
                        name: name(text),
                    })
                }
            }
            Tok::Int(value) => Ok(Expr::Int { pos, value }),
            Tok::Float(value) => Ok(Expr::Float { pos, value }),
            Tok::Quote => self.parse_string_rest(pos),
            Tok::IndStringOpen => self.parse_ind_string_rest(pos),
            Tok::Path(literal) => {
                let literal = std::str::from_utf8(literal).expect("path characters are ASCII");
                // `path_start`: the lints see the first piece of the path,
                // before anything after it is read.
                let anchor = if literal.starts_with('/') {
                    self.diagnose(self.lints.absolute_path_literals, "lint-absolute-path-literals", pos, |_| {
                        format!("absolute path literals are not portable. Consider replacing path literal '{literal}' by a string, relative path, or parameter")
                    })?;
                    PathAnchor::Root
                } else {
                    if !literal.starts_with('.') {
                        self.diagnose(self.lints.short_path_literals, "lint-short-path-literals", pos, |_| {
                            format!("relative path literal '{literal}' should be prefixed with '.' for clarity: './{literal}'")
                        })?;
                    }
                    PathAnchor::Source
                };
                let start = Expr::Path {
                    pos,
                    anchor,
                    path: resolve_path_literal(literal, self.base_dir),
                };
                self.parse_path_rest(pos, start)
            }
            // Pure evaluation rejects these before `lint-absolute-path-literals`
            // would look at them.
            Tok::HPath(literal) => Err(ParseError {
                msg: [
                    &b"the path '"[..],
                    literal,
                    b"' can not be resolved in pure mode",
                ]
                .concat()
                .into(),
                pos: None,
                defined_at: None,
            }),
            Tok::SPath(text) => {
                let inner = &text[1..text.len() - 1];
                Ok(Expr::Call {
                    pos,
                    fun: boxed(var(Pos::NONE, "__findFile")),
                    args: vec![
                        var(Pos::NONE, "__nixPath"),
                        Expr::String {
                            pos: Pos::NONE,
                            value: inner.to_vec(),
                        },
                    ],
                })
            }
            Tok::Uri(text) => {
                self.diagnose(self.lints.url_literals, "lint-url-literals", pos, |fatal| {
                    format!(
                        "URL literals are {}. Consider using a string literal \"{}\" instead",
                        if fatal { "disallowed" } else { "discouraged" },
                        String::from_utf8_lossy(text)
                    )
                })?;
                Ok(Expr::String {
                    pos,
                    value: text.to_vec(),
                })
            }
            Tok::LParen => {
                let e = self.parse_expr()?;
                self.expect(Tok::RParen)?;
                Ok(e)
            }
            Tok::Let => {
                // `let { …; body = …; }` is `(rec { … }).body`.
                self.expect(Tok::LBrace)?;
                let mut attrs = self.parse_binds(BindsContext::RecBraces)?;
                attrs.recursive = true;
                attrs.pos = pos;
                Ok(Expr::Select {
                    pos: Pos::NONE,
                    subject: boxed(Expr::Attrs(Box::new(attrs))),
                    path: vec![AttrName::Static(Name::from("body"))],
                    default: None,
                })
            }
            Tok::Rec => {
                self.expect(Tok::LBrace)?;
                let mut attrs = self.parse_binds(BindsContext::RecBraces)?;
                attrs.recursive = true;
                attrs.pos = pos;
                Ok(Expr::Attrs(Box::new(attrs)))
            }
            Tok::LBrace => {
                if self.at(Tok::RBrace)? {
                    self.bump()?;
                    return Ok(Expr::Attrs(Box::new(AttrSet {
                        pos,
                        ..AttrSet::default()
                    })));
                }
                let mut attrs = self.parse_binds(BindsContext::Braces)?;
                attrs.pos = pos;
                Ok(Expr::Attrs(Box::new(attrs)))
            }
            // Elements are parsed without going through `parse_expr`, so a
            // list nested in a list grows the stack here.
            Tok::LBracket => stacker::maybe_grow(STACK_RED_ZONE, STACK_SEGMENT, || {
                let mut elems = Vec::new();
                while starts_simple(self.peek_tok()?) {
                    elems.push(self.parse_expr_select_warn()?);
                }
                if !self.at(Tok::RBracket)? {
                    return Err(self.syntax_error(None));
                }
                self.bump()?;
                Ok(Expr::List { pos, elems })
            }),
            _ => Err(syntax_error_at(&tok, None)),
        }
    }

    // ----- strings and paths ----------------------------------------------

    /// After the opening `"`: `string_parts '"'`.
    fn parse_string_rest(&mut self, pos: Pos) -> Result<Expr, ParseError> {
        let mut parts: Vec<(Pos, Expr)> = Vec::new();
        let mut interpolated = false;
        loop {
            let tok = self.bump()?;
            let tpos = tok.pos();
            match tok.tok {
                Tok::Str(value) => parts.push((tpos, Expr::String { pos: tpos, value })),
                Tok::DollarCurly => {
                    interpolated = true;
                    let e = self.parse_expr()?;
                    self.expect(Tok::RBrace)?;
                    parts.push((tpos, e));
                }
                Tok::Quote => break,
                _ => return Err(syntax_error_at(&tok, Some("'\"'"))),
            }
        }
        if !interpolated {
            // Taken rather than moved out: `Expr` has a destructor.
            let mut last = parts.pop();
            let value = match &mut last {
                Some((_, Expr::String { value, .. })) => std::mem::take(value),
                _ => Vec::new(),
            };
            return Ok(Expr::String { pos, value });
        }
        // parser.y: `string_parts: string_parts_interpolated { … CUR_POS … }`,
        // so the position is that of the first part (the first `STR` or
        // `${`), not of the opening quote.
        let first_part_pos = parts.first().map_or(pos, |(p, _)| *p);
        Ok(Expr::ConcatStrings {
            pos: first_part_pos,
            force_string: true,
            parts,
        })
    }

    /// After `''`: `ind_string_parts IND_STRING_CLOSE`.
    fn parse_ind_string_rest(&mut self, pos: Pos) -> Result<Expr, ParseError> {
        let mut parts: Vec<(Pos, IndPart)> = Vec::new();
        loop {
            let tok = self.bump()?;
            let tpos = tok.pos();
            match tok.tok {
                Tok::IndStr {
                    text,
                    has_indentation,
                } => parts.push((
                    tpos,
                    IndPart::Str {
                        text,
                        has_indentation,
                    },
                )),
                Tok::DollarCurly => {
                    let e = self.parse_expr()?;
                    self.expect(Tok::RBrace)?;
                    parts.push((tpos, IndPart::Expr(e)));
                }
                Tok::IndStringClose => break,
                _ => {
                    return Err(syntax_error_at(
                        &tok,
                        Some("indented string or '${' or end of an indented string"),
                    ))
                }
            }
        }
        Ok(strip_indentation(pos, parts))
    }

    /// After the first piece of a path: either the end of the path, or an
    /// interpolated continuation (`string_parts_interpolated PATH_END`).
    fn parse_path_rest(&mut self, pos: Pos, start: Expr) -> Result<Expr, ParseError> {
        let mut parts: Vec<(Pos, Expr)> = vec![(pos, start)];
        if !self.at(Tok::DollarCurly)? {
            let tok = self.bump()?;
            let tpos = tok.pos();
            match tok.tok {
                Tok::PathEnd => return Ok(parts.pop().expect("the path start").1),
                Tok::Str(value) => {
                    parts.push((tpos, Expr::String { pos: tpos, value }));
                    if !self.at(Tok::DollarCurly)? {
                        return Err(self.syntax_error(Some("'${'")));
                    }
                }
                _ => return Err(syntax_error_at(&tok, None)),
            }
        }
        loop {
            let tok = self.bump()?;
            let tpos = tok.pos();
            match tok.tok {
                Tok::DollarCurly => {
                    let e = self.parse_expr()?;
                    self.expect(Tok::RBrace)?;
                    parts.push((tpos, e));
                }
                Tok::Str(value) => parts.push((tpos, Expr::String { pos: tpos, value })),
                Tok::PathEnd => break,
                _ => return Err(syntax_error_at(&tok, None)),
            }
        }
        Ok(Expr::ConcatStrings {
            pos,
            force_string: false,
            parts,
        })
    }

    // ----- attribute paths and bindings -----------------------------------

    /// `attrpath`: one or more `attr`/`string_attr` separated by dots.
    fn parse_attrpath(&mut self) -> Result<Vec<AttrName>, ParseError> {
        let mut path = Vec::new();
        loop {
            path.push(self.parse_attr_name()?);
            if self.at(Tok::Dot)? {
                self.bump()?;
            } else {
                return Ok(path);
            }
        }
    }

    /// One component of an attribute path. `"…"` and `${…}` are static when
    /// their content is a literal string (`ToBeStringyExpr::visit`).
    fn parse_attr_name(&mut self) -> Result<AttrName, ParseError> {
        let tok = self.bump()?;
        let tpos = tok.pos();
        match tok.tok {
            Tok::Id(text) => Ok(AttrName::Static(name(text))),
            Tok::OrKw => Ok(AttrName::Static(Name::from("or"))),
            Tok::Quote => Ok(attr_name_of(self.parse_string_rest(tpos)?)),
            Tok::DollarCurly => {
                let e = self.parse_expr()?;
                self.expect(Tok::RBrace)?;
                Ok(attr_name_of(e))
            }
            _ => Err(syntax_error_at(&tok, Some(EXPECTING_ATTR))),
        }
    }

    /// `binds` up to and including the closing token of `ctx`.
    fn parse_binds(&mut self, ctx: BindsContext) -> Result<AttrSet, ParseError> {
        let mut attrs = AttrSet::default();
        let mut index = AttrIndex::default();
        loop {
            if self.at(ctx.closer())? {
                self.bump()?;
                return Ok(attrs);
            }
            let tpos = self.peek_pos()?;
            if self.at(Tok::Inherit)? {
                self.bump()?;
                let from = if self.at(Tok::LParen)? {
                    self.bump()?;
                    let e = self.parse_expr()?;
                    self.expect(Tok::RParen)?;
                    attrs.inherit_from.push(e);
                    Some((attrs.inherit_from.len() - 1) as u32)
                } else {
                    None
                };
                let names = self.parse_inherit_attrs()?;
                if !self.at(Tok::Semi)? {
                    return Err(self.syntax_error(None));
                }
                self.bump()?;
                // Duplicates are found when bison reduces the clause, after
                // its `;`.
                for (name, pos) in names {
                    if let Some(prev) = index.get(&name) {
                        return Err(dup_inherit(&name, pos, attrs.attrs[*prev].pos));
                    }
                    index.insert(name.clone(), attrs.attrs.len());
                    attrs.attrs.push(AttrDef {
                        name,
                        pos,
                        value: match from {
                            Some(index) => AttrValue::InheritedFrom { index },
                            None => AttrValue::Inherited,
                        },
                    });
                }
            } else if starts_attr(self.peek_tok()?) {
                let path = self.parse_attrpath()?;
                if !self.at(Tok::Assign)? {
                    return Err(self.syntax_error(Some("'.' or '='")));
                }
                self.bump()?;
                let value = self.parse_expr()?;
                self.expect(Tok::Semi)?;
                add_attr(&mut attrs, &mut index, path, tpos, value)?;
            } else {
                return Err(self.syntax_error(Some(ctx.expecting())));
            }
        }
    }

    /// `attrs` after `inherit` (and after `inherit (…)`): names, which may
    /// be quoted but not dynamic.
    fn parse_inherit_attrs(&mut self) -> Result<Vec<(Name, Pos)>, ParseError> {
        let mut names = Vec::new();
        while starts_attr(self.peek_tok()?) {
            let tpos = self.peek_pos()?;
            match self.parse_attr_name()? {
                AttrName::Static(name) => names.push((name, tpos)),
                AttrName::Dynamic(_) => {
                    return Err(ParseError::new(
                        "dynamic attributes not allowed in inherit",
                        tpos,
                    ))
                }
            }
        }
        Ok(names)
    }
}

/// "syntax error, unexpected X[, expecting Y]". Bison positions an
/// unexpected end of file at the end of the last token rather than at its
/// start.
fn syntax_error_at(tok: &Token<'_>, expecting: Option<&str>) -> ParseError {
    let pos = if tok.tok == Tok::Eof {
        tok.end
    } else {
        tok.start
    };
    let mut msg = format!("syntax error, unexpected {}", tok.tok.describe());
    if let Some(expecting) = expecting {
        msg.push_str(", expecting ");
        msg.push_str(expecting);
    }
    ParseError::new(msg, Pos(pos))
}

fn id_name(tok: &Token<'_>) -> Name {
    match &tok.tok {
        Tok::Id(text) => name(text),
        _ => unreachable!("not an identifier"),
    }
}

/// `validateFormals`: no formal twice, and the `@` name not among them.
fn validate_formals(formals: &Formals, pos: Pos, arg: Option<&Name>) -> Result<(), ParseError> {
    // Nix sorts by (symbol, position) and reports the smallest duplicate.
    // Symbols order by creation, which within one file is first
    // appearance, so the first repeated name wins, at the position of its
    // second occurrence.
    for (i, f) in formals.formals.iter().enumerate() {
        if formals.formals[..i].iter().any(|g| g.name == f.name) {
            continue;
        }
        let mut positions: Vec<Pos> = formals.formals[i..]
            .iter()
            .filter(|g| g.name == f.name)
            .map(|g| g.pos)
            .collect();
        if positions.len() > 1 {
            positions.sort();
            return Err(duplicate_formal(&f.name, positions[1]));
        }
    }
    if let Some(arg) = arg {
        if formals.formals.iter().any(|f| &f.name == arg) {
            return Err(duplicate_formal(arg, pos));
        }
    }
    Ok(())
}

/// "duplicate formal function argument 'x'", the name as it is.
fn duplicate_formal(name: &Name, pos: Pos) -> ParseError {
    let msg = [
        &b"duplicate formal function argument '"[..],
        name.as_bytes(),
        b"'",
    ]
    .concat();
    ParseError::new(msg, pos)
}

/// `makeCall`: an application of a call is one call with more arguments.
fn make_call(pos: Pos, mut fun: Expr, arg: Expr) -> Expr {
    if let Expr::Call { args, .. } = &mut fun {
        args.push(arg);
        return fun;
    }
    Expr::Call {
        pos,
        fun: boxed(fun),
        args: vec![arg],
    }
}

fn attr_name_of(e: Expr) -> AttrName {
    if let Expr::String { value, .. } = &e {
        return AttrName::Static(name(value));
    }
    AttrName::Dynamic(boxed(e))
}

/// Builds the node for a binary operator, applying `parser.y`'s
/// desugarings. `lhs_start`/`rhs_start` are the operands' first-token
/// positions, which `+` records on its parts.
fn build_binary(
    tok: &Tok<'_>,
    op_pos: Pos,
    lhs_start: Pos,
    lhs: Expr,
    rhs_start: Pos,
    rhs: Expr,
) -> Expr {
    let call = |name_: &str, args: Vec<Expr>| Expr::Call {
        pos: op_pos,
        fun: boxed(var(Pos::NONE, name_)),
        args,
    };
    let binop = |op: BinOp, lhs: Expr, rhs: Expr| Expr::BinOp {
        pos: op_pos,
        op,
        lhs: boxed(lhs),
        rhs: boxed(rhs),
    };
    match tok {
        Tok::Eq => binop(BinOp::Eq, lhs, rhs),
        Tok::NEq => binop(BinOp::NEq, lhs, rhs),
        Tok::And => binop(BinOp::And, lhs, rhs),
        Tok::Or => binop(BinOp::Or, lhs, rhs),
        Tok::Impl => binop(BinOp::Impl, lhs, rhs),
        Tok::Update => binop(BinOp::Update, lhs, rhs),
        Tok::Concat => binop(BinOp::ConcatLists, lhs, rhs),
        Tok::Lt => call("__lessThan", vec![lhs, rhs]),
        Tok::Gt => call("__lessThan", vec![rhs, lhs]),
        Tok::Leq => Expr::Not(boxed(call("__lessThan", vec![rhs, lhs]))),
        Tok::Geq => Expr::Not(boxed(call("__lessThan", vec![lhs, rhs]))),
        Tok::Plus => Expr::ConcatStrings {
            pos: op_pos,
            force_string: false,
            parts: vec![(lhs_start, lhs), (rhs_start, rhs)],
        },
        Tok::Minus => call("__sub", vec![lhs, rhs]),
        Tok::Star => call("__mul", vec![lhs, rhs]),
        Tok::Slash => call("__div", vec![lhs, rhs]),
        _ => unreachable!("not a binary operator"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    use crate::source::Origin;

    /// Parses with `options`, returning the result and the warnings.
    fn parse_with(src: &str, options: &ParseOptions) -> (Result<Expr, ParseError>, Vec<Warning>) {
        let mut warnings = Vec::new();
        let result = parse(src.as_bytes(), "/pwd", options, &mut warnings);
        (result, warnings)
    }

    fn parse_ok(src: &str) -> Expr {
        let (result, warnings) = parse_with(src, &ParseOptions::default());
        assert_eq!(warnings, vec![], "for {src:?}");
        result.expect("parses")
    }

    fn parse_err(src: &str) -> ParseError {
        parse_with(src, &ParseOptions::default())
            .0
            .expect_err("fails")
    }

    /// The error as `nix` prints it for stdin, without the code lines.
    fn error_message(src: &str) -> String {
        String::from_utf8(parse_err(src).message(&Origin::Stdin, src.as_bytes()))
            .expect("the messages tested are text")
    }

    #[test]
    fn positions_follow_nix() {
        // Lambda at its argument, call at its function, select at its
        // subject, binary operators at the operator.
        let lambda = parse_ok("  x: f x.y + 1");
        let Expr::Lambda { pos, body, .. } = &lambda else {
            panic!()
        };
        assert_eq!(*pos, Pos(2));
        let Expr::ConcatStrings { pos, parts, .. } = &**body else {
            panic!()
        };
        assert_eq!(*pos, Pos(11));
        assert_eq!(parts[0].0, Pos(5));
        assert_eq!(parts[1].0, Pos(13));
        let Expr::Call { pos, args, .. } = &parts[0].1 else {
            panic!()
        };
        assert_eq!(*pos, Pos(5));
        assert_eq!(args[0].pos(), Pos(7));
    }

    #[test]
    fn literals_report_no_position() {
        assert_eq!(parse_ok("1").pos(), Pos::NONE);
        assert_eq!(parse_ok("\"a\"").pos(), Pos::NONE);
        assert_eq!(parse_ok("./a").pos(), Pos::NONE);
        assert_eq!(parse_ok("1.5").pos(), Pos::NONE);
    }

    #[test]
    fn desugared_operators_have_no_variable_position() {
        let sub = parse_ok("1 - 2");
        let Expr::Call { fun, pos, .. } = &sub else {
            panic!()
        };
        assert_eq!(*pos, Pos(2));
        assert_eq!(fun.pos(), Pos::NONE);
        let neg = parse_ok("- 2");
        let Expr::Call { pos, args, .. } = &neg else {
            panic!()
        };
        assert_eq!(*pos, Pos(0));
        assert_eq!(args.len(), 2);
    }

    #[test]
    fn eof_errors_point_past_the_input() {
        let err = parse_err("a.");
        assert_eq!(
            err.msg,
            "syntax error, unexpected end of file, expecting identifier or 'or' or '${' or '\"'"
        );
        assert_eq!(err.pos, Some(Pos(2)));
        let err = parse_err("# only\n");
        assert_eq!(err.msg, "syntax error, unexpected end of file");
        assert_eq!(err.pos, Some(Pos(7)));
    }

    #[test]
    fn nonassoc_operators() {
        assert_eq!(
            parse_err("x: x == x == x").msg,
            "syntax error, unexpected '=='"
        );
        assert_eq!(
            parse_err("x: x < x > x").msg,
            "syntax error, unexpected '>'"
        );
        // `?` chains, `-` and `!` bind as in Nix.
        parse_ok("x: x ? a ? b");
    }

    #[test]
    fn errors_match_nix_messages() {
        for (src, msg) in [
            (
                "{ 1 = x; }",
                "syntax error, unexpected integer, expecting 'inherit'",
            ),
            (
                "rec { 5 }",
                "syntax error, unexpected integer, expecting 'inherit' or '}'",
            ),
            (
                "let 5 in 5",
                "syntax error, unexpected integer, expecting 'in' or 'inherit'",
            ),
            (
                "{ a ... }",
                "syntax error, unexpected '...', expecting '.' or '='",
            ),
            (
                "{ a, b } 1",
                "syntax error, unexpected integer, expecting ':' or '@'",
            ),
            (
                "{ a ? 1 , 2 }: 1",
                "syntax error, unexpected integer, expecting identifier or '...' or '}'",
            ),
            (
                "x: x @",
                "syntax error, unexpected end of file, expecting '{'",
            ),
            (
                "if 1 else",
                "syntax error, unexpected 'else', expecting 'then'",
            ),
            ("(1 ;", "syntax error, unexpected ';', expecting ')'"),
            ("1 )", "syntax error, unexpected ')', expecting end of file"),
            ("[ 1 ;", "syntax error, unexpected ';'"),
            (
                "./foo//bar",
                "syntax error, unexpected end of path, expecting '${'",
            ),
            (
                "1 ~ 2",
                "syntax error, unexpected invalid token, expecting end of file",
            ),
            ("{ inherit http://x; }", "syntax error, unexpected URI"),
            (
                "x: { inherit ${x}; }",
                "dynamic attributes not allowed in inherit",
            ),
            (
                "x: let ${x} = 1; in 1",
                "dynamic attributes not allowed in let",
            ),
            ("{x, y, x}: x", "duplicate formal function argument 'x'"),
            (
                "args@{args}: 1",
                "duplicate formal function argument 'args'",
            ),
            ("~/foo", "the path '~/foo' can not be resolved in pure mode"),
            // Checks bison makes when it reduces a rule come after any
            // error in the rest of the rule.
            ("{ a, a }: (", "syntax error, unexpected end of file"),
            ("a@{ a }: (", "syntax error, unexpected end of file"),
            ("{ a }@a: (", "syntax error, unexpected end of file"),
            (
                "{ a, a }: { b = 1; b = 2; }",
                "attribute 'b' already defined at «stdin»:1:13",
            ),
            ("{ a = 1; inherit a }", "syntax error, unexpected '}'"),
            ("{ a = 1; inherit (x) a }", "syntax error, unexpected '}'"),
            ("let a = 1; inherit a in 1", "syntax error, unexpected 'in'"),
            (
                "{ a = 1; inherit a a; }",
                "attribute 'a' already defined at «stdin»:1:3",
            ),
            (
                "{ inherit a ${b}; a = 1; }",
                "dynamic attributes not allowed in inherit",
            ),
            (
                "x: let ${x} = 1; in (",
                "syntax error, unexpected end of file",
            ),
            (
                "x: let ${x} = 1; a = 1; a = 2; in x",
                "attribute 'a' already defined at «stdin»:1:18",
            ),
        ] {
            assert_eq!(error_message(src), msg, "for {src:?}");
        }
    }

    #[test]
    fn attribute_merging_and_duplicates() {
        let err = parse_err("{ x.z = 3; x = { y = 3; z = 3; }; }");
        assert_eq!(err.msg, "attribute 'x.z' already defined");
        assert_eq!(err.pos, Some(Pos(24)));
        assert_eq!(err.defined_at, Some(Pos(2)));
        assert_eq!(
            error_message("{ a = 1; inherit a; }"),
            "attribute 'a' already defined at «stdin»:1:3"
        );
        assert_eq!(
            error_message("x: { x.a = 1; x = rec { inherit (x) b; }; x = { inherit (x) a; }; }"),
            "attribute 'x.a' already defined at «stdin»:1:6"
        );
    }

    #[test]
    fn cursed_or_warns_where_nix_does() {
        let warnings = |src: &str| parse_with(src, &ParseOptions::default()).1;
        // An argument, a list element, the default of a select.
        assert_eq!(
            warnings("f (x: x) or"),
            vec![Warning::CursedOr {
                pos: Pos(2),
                end: Pos(11)
            }]
        );
        assert_eq!(
            warnings("[ (x: x) or ]"),
            vec![Warning::CursedOr {
                pos: Pos(2),
                end: Pos(11)
            }]
        );
        assert_eq!(
            warnings("{ a = 2; }.a or (x: x) or"),
            vec![Warning::CursedOr {
                pos: Pos(16),
                end: Pos(25)
            }]
        );
        // The first expression of an application is not cursed.
        assert_eq!(warnings("map or [ ]"), vec![]);
        assert_eq!(warnings("f (f or)"), vec![]);
        assert_eq!(warnings("x.or"), vec![]);
    }

    #[test]
    fn lints() {
        let at = |level: Diagnose| ParseOptions {
            lints: Lints {
                url_literals: level,
                short_path_literals: level,
                absolute_path_literals: level,
            },
            ..ParseOptions::default()
        };
        // Ignored by default.
        parse_ok("[ http://x foo/bar /abs ]");
        let (result, warnings) =
            parse_with("[ http://x foo/bar /abs ./rel ../up ]", &at(Diagnose::Warn));
        result.expect("warnings do not stop parsing");
        let msgs: Vec<String> = warnings
            .iter()
            .map(|w| match w {
                Warning::Lint { msg, .. } => msg.clone(),
                other => panic!("{other:?}"),
            })
            .collect();
        assert_eq!(msgs, vec![
            "URL literals are discouraged. Consider using a string literal \"http://x\" instead (lint-url-literals)",
            "relative path literal 'foo/bar' should be prefixed with '.' for clarity: './foo/bar' (lint-short-path-literals)",
            "absolute path literals are not portable. Consider replacing path literal '/abs' by a string, relative path, or parameter (lint-absolute-path-literals)",
        ]);
        // Fatal: the first one found is the error, before anything after
        // the literal is read.
        let (result, warnings) = parse_with("http://x ~", &at(Diagnose::Fatal));
        assert_eq!(
            result.expect_err("fatal").msg,
            "URL literals are disallowed. Consider using a string literal \"http://x\" instead (lint-url-literals)"
        );
        assert_eq!(warnings, vec![]);
        let (result, _) = parse_with("foo/bar/", &at(Diagnose::Fatal));
        assert_eq!(
            result.expect_err("fatal").pos,
            Some(Pos(0)),
            "the lint comes before the trailing-slash error"
        );
        // Warnings found before an error are kept.
        let (result, warnings) = parse_with("[ a/b (", &at(Diagnose::Warn));
        result.expect_err("syntax error");
        assert_eq!(warnings.len(), 1);
    }

    /// `makeCall(state->at(@2), …)`: a pipe's call is positioned at the
    /// operator, unless it merges into a call, which keeps its position.
    /// (`nix-instantiate --parse` does not show positions; the printed
    /// trees are compared with Nix in tests/oracle.rs.)
    #[test]
    fn pipe_calls_are_positioned_at_the_operator() {
        let pipes = ParseOptions {
            pipe_operators: true,
            ..ParseOptions::default()
        };
        let call_pos = |src: &str| match &parse_with(src, &pipes).0.expect("parses") {
            Expr::Call { pos, args, .. } => (*pos, args.len()),
            other => panic!("{src:?}: {other:?}"),
        };
        assert_eq!(call_pos("x |> f"), (Pos(2), 1));
        assert_eq!(call_pos("f <| x"), (Pos(2), 1));
        assert_eq!(call_pos("x |> f a"), (Pos(5), 2));
        assert_eq!(call_pos("f a <| x"), (Pos(0), 2));
        // `f <| g <| x`: the outer call at the first `<|`, the inner one
        // at the second.
        let Expr::Call { pos, ref args, .. } = parse_with("f <| g <| x", &pipes).0.unwrap() else {
            panic!()
        };
        assert_eq!(pos, Pos(2));
        assert!(matches!(args[0], Expr::Call { pos: Pos(7), .. }));
        // `x |> f |> g`: the outer call at the second `|>`.
        let Expr::Call { pos, ref args, .. } = parse_with("x |> f |> g", &pipes).0.unwrap() else {
            panic!()
        };
        assert_eq!(pos, Pos(7));
        assert!(matches!(args[0], Expr::Call { pos: Pos(2), .. }));
    }

    #[test]
    fn indentation_is_capped_like_nix() {
        // With no line that has anything on it, Nix's minimum indentation
        // keeps its starting value: at most 1000000 spaces are dropped.
        let src = format!("''\n{}\n''", " ".repeat(1_000_003));
        let Expr::String { ref value, .. } = parse_ok(&src) else {
            panic!("a plain string")
        };
        assert_eq!(value, b"   \n");
    }
}
